 private void openBio(BiometricCaptureView.Mode mode,boolean simulation){try{BiometricCaptureView v=new BiometricCaptureView(user.id(),bio,user.role().equals("SECURITY"));javafx.stage.Window owner=content.getScene().getWindow();if(simulation)v.showSimulation((javafx.stage.Stage)owner,mode);else v.show((javafx.stage.Stage)owner,mode);}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Biometric module error: "+ex.getMessage()).showAndWait();}biometrics();}
 private void softwareTest(){BiometricCaptureView v=new BiometricCaptureView(user.id(),bio);Alert a=new Alert(Alert.AlertType.CONFIRMATION);a.setTitle("Hardware-Free Test");a.setHeaderText("Choose a software test");ButtonType face= new ButtonType("Face Enroll");ButtonType palm=new ButtonType("Palm Enroll");ButtonType live=new ButtonType("Liveness");a.getButtonTypes().setAll(face,palm,live,ButtonType.CANCEL);ButtonType r=a.showAndWait().orElse(ButtonType.CANCEL);if(r==face)v.showSimulation((javafx.stage.Stage)content.getScene().getWindow(),BiometricCaptureView.faceEnroll());else if(r==palm)v.showSimulation((javafx.stage.Stage)content.getScene().getWindow(),BiometricCaptureView.palmEnroll());else if(r==live)v.showSimulation((javafx.stage.Stage)content.getScene().getWindow(),BiometricCaptureView.liveness());biometrics();}
