   Button assignFaculty=App.btn("ASSIGN FACULTY TO SUBJECT");assignFaculty.setOnAction(e->{try{if(facultyChoice.getValue()==null)throw new IllegalArgumentException("Select an active faculty member.");if(facultySubjectChoice.getValue()==null)throw new IllegalArgumentException("Select a subject.");long facultyId=Long.parseLong(facultyChoice.getValue().split("\\s*\\|")[0].trim());long subjectId=Long.parseLong(facultySubjectChoice.getValue().split("\\s*\\|")[0].trim());academic.assignFacultyToSubject(user.id(),facultyId,subjectId);new Alert(Alert.AlertType.INFORMATION,"Faculty assigned successfully. The subject is now available in the faculty portal.").showAndWait();loadFacultyAssignments.run();}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Unable to assign faculty: "+ex.getMessage()).showAndWait();}});
