   ListView<String> timetableRows=new ListView<>();timetableRows.setPrefHeight(190);
   Runnable loadTimetable=()->{try{timetableRows.getItems().setAll(academic.listTimetableEntries(user.id()));if(timetableRows.getItems().isEmpty())timetableRows.getItems().add("No timetable entries found.");}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Unable to load timetable: "+ex.getMessage()).showAndWait();}};
   ComboBox<String> timetableSubject=new ComboBox<>();timetableSubject.setMaxWidth(Double.MAX_VALUE);timetableSubject.setPromptText("Select subject");timetableSubject.getItems().addAll(academic.listSubjects().stream().map(row->{String[] parts=row.split("\\s*\\|",4);return parts.length>=3?parts[0].replace("#","").trim()+" | "+parts[1].trim()+" - "+parts[2].trim():row;}).toList());
   ComboBox<String> timetableRoom=new ComboBox<>();timetableRoom.setMaxWidth(Double.MAX_VALUE);timetableRoom.setPromptText("Select classroom (optional)");timetableRoom.getItems().add("0 | No classroom");timetableRoom.getItems().addAll(academic.classroomOptions());
   ComboBox<String> timetableDay=new ComboBox<>();timetableDay.getItems().addAll("MONDAY","TUESDAY","WEDNESDAY","THURSDAY","FRIDAY","SATURDAY");timetableDay.setValue("MONDAY");timetableDay.setMaxWidth(Double.MAX_VALUE);
   TextField timetableStart=new TextField("09:00");timetableStart.setPromptText("Start time HH:mm");TextField timetableEnd=new TextField("10:00");timetableEnd.setPromptText("End time HH:mm");
   Button saveTimetable=App.btn("CREATE TIMETABLE ENTRY");Button clearTimetable=App.btn("CLEAR / NEW ENTRY");Button deleteTimetable=App.btn("DELETE SELECTED ENTRY");Button refreshTimetable=App.btn("REFRESH TIMETABLE");
   final long[] selectedTimetableId={0};
   timetableRows.getSelectionModel().selectedItemProperty().addListener((obs,oldValue,newValue)->{if(newValue==null||!newValue.startsWith("#"))return;try{long selectedId=Long.parseLong(newValue.substring(1).split("\\s*\\|")[0].trim());String[] d=academic.timetableDetails(user.id(),selectedId);selectedTimetableId[0]=selectedId;for(String option:timetableSubject.getItems())if(option.split("\\s*\\|")[0].trim().equals(d[0])){timetableSubject.setValue(option);break;}for(String option:timetableRoom.getItems())if(option.split("\\s*\\|")[0].trim().equals(d[1].isEmpty()?"0":d[1])){timetableRoom.setValue(option);break;}timetableDay.setValue(d[2]);timetableStart.setText(d[3].substring(0,5));timetableEnd.setText(d[4].substring(0,5));saveTimetable.setText("UPDATE SELECTED ENTRY");}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Unable to load selected entry: "+ex.getMessage()).showAndWait();}});
   clearTimetable.setOnAction(e->{selectedTimetableId[0]=0;timetableRows.getSelectionModel().clearSelection();timetableSubject.setValue(null);timetableRoom.setValue(null);timetableDay.setValue("MONDAY");timetableStart.setText("09:00");timetableEnd.setText("10:00");saveTimetable.setText("CREATE TIMETABLE ENTRY");});
   saveTimetable.setOnAction(e->{try{if(timetableSubject.getValue()==null)throw new IllegalArgumentException("Select a subject.");long subjectId=Long.parseLong(timetableSubject.getValue().split("\\s*\\|")[0].trim());String roomValue=timetableRoom.getValue();Long roomId=roomValue==null||roomValue.startsWith("0 ")?null:Long.parseLong(roomValue.split("\\s*\\|")[0].trim());if(selectedTimetableId[0]==0)academic.createTimetableEntry(user.id(),subjectId,roomId,timetableDay.getValue(),timetableStart.getText().trim(),timetableEnd.getText().trim());else academic.updateTimetableEntry(user.id(),selectedTimetableId[0],subjectId,roomId,timetableDay.getValue(),timetableStart.getText().trim(),timetableEnd.getText().trim());new Alert(Alert.AlertType.INFORMATION,"Timetable entry saved successfully.").showAndWait();clearTimetable.fire();loadTimetable.run();}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Unable to save timetable: "+ex.getMessage()).showAndWait();}});
   deleteTimetable.setOnAction(e->{if(selectedTimetableId[0]==0){new Alert(Alert.AlertType.WARNING,"Select a timetable entry first.").showAndWait();return;}Alert confirm=new Alert(Alert.AlertType.CONFIRMATION,"Delete the selected timetable entry?");if(confirm.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK)try{academic.deleteTimetableEntry(user.id(),selectedTimetableId[0]);clearTimetable.fire();loadTimetable.run();}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Unable to delete timetable entry: "+ex.getMessage()).showAndWait();}});
